mapper.select:
select count(*) from tb_product_detail
where product_state='R' or product_state='O'
;

mapper.update:
update tb_product_detail
set rental_date=CURRENT_DATE, order_reason=null, product_state='Y', approve='Y'
where category_code=#{category_code} and product_detail_code=#{product_detail_code};

update tb_use_history
set rental_date=current_date, product_state='Y'
where loginId=#{loginID} and category_code=#{category_code} and product_detail_code=#{product_detail_code} and product_state='O';

update tb_product_detail
set rental_date=null, product_state='N', approve='N'
where category_code=#{category_code} and product_detail_code=#{product_detail_code};

update tb_use_history
set  rental_date=null, product_state='N'
where loginId=#{loginID} and category_code=#{category_code} and product_detail_code=#{product_detail_code} and product_state='O';

update tb_product_detail
set loginID=null, order_date=null, rental_date=null, return_date=null, order_reason=null, product_state='N', approve='Y'
where category_code=#{category_code} and product_detail_code=#{product_detail_code};

update tb_product_detail
set return_date=null, product_state='Y', approve='N'
where category_code=#{category_code} and product_detail_code=#{product_detail_code};

update tb_use_history
set return_date=null, product_state='Y'
where loginID=#{loginID} and category_code=#{category_code} and product_detail_code=#{product_detail_code} and product_state='R';

mapper.select:
select pd.category_code,pd.product_detail_code,ui.loginID,ui.name, pinfo.product_name,pd.order_date, pd.product_state, pd.order_reason, pd.approve
from tb_product_detail pd
left outer join tb_userinfo ui on pd.loginID = ui.loginID
left outer join tb_product_info pinfo on pd.product_no = pinfo.product_no
where (product_state='R' or product_state='O')



            AND pd.category_code=#{category_code}


            AND pd.product_detail_code=#{product_detail_code}



        AND ui.name=#{searchWordStr}


        AND pd.order_date=#{searchWordStr}





;
